import { sql, type Kysely } from 'kysely';

/**
 * 0001 — Core tables.
 *
 * Conventions:
 * - Primary keys are UUIDs generated by Postgres (gen_random_uuid()).
 * - Every tenant-owned table has a NOT NULL tenant_id with an index.
 * - Times are `timestamptz` (stored in UTC). Money is integer paise.
 * - CHECK constraints guard against impossible data even if app code has a bug.
 */
export async function up(db: Kysely<unknown>): Promise<void> {
  await sql`
    CREATE EXTENSION IF NOT EXISTS btree_gist;

    CREATE TYPE membership_role AS ENUM ('OWNER', 'STAFF', 'CUSTOMER');
    CREATE TYPE booking_status AS ENUM ('HELD', 'CONFIRMED', 'COMPLETED', 'NO_SHOW', 'EXPIRED', 'CANCELLED');
    CREATE TYPE payment_status AS ENUM ('CREATED', 'CAPTURED', 'FAILED', 'REFUND_PENDING', 'REFUNDED');
    CREATE TYPE notification_type AS ENUM ('BOOKING_CONFIRMED', 'BOOKING_REMINDER', 'BOOKING_CANCELLED', 'LATE_PAYMENT_REFUNDED');
    CREATE TYPE notification_status AS ENUM ('PENDING', 'SENT', 'FAILED', 'CANCELLED');

    CREATE TABLE tenants (
      id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
      name text NOT NULL CHECK (length(name) BETWEEN 1 AND 120),
      slug text NOT NULL UNIQUE CHECK (slug ~ '^[a-z0-9](-?[a-z0-9])*$' AND length(slug) BETWEEN 3 AND 40),
      timezone text NOT NULL DEFAULT 'Asia/Kolkata',
      currency char(3) NOT NULL DEFAULT 'INR',
      cancellation_window_hours integer NOT NULL DEFAULT 24 CHECK (cancellation_window_hours BETWEEN 0 AND 720),
      booking_horizon_days integer NOT NULL DEFAULT 60 CHECK (booking_horizon_days BETWEEN 1 AND 365),
      created_at timestamptz NOT NULL DEFAULT now()
    );

    CREATE TABLE users (
      id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
      email text NOT NULL UNIQUE CHECK (email = lower(email)),
      name text NOT NULL CHECK (length(name) BETWEEN 1 AND 120),
      password_hash text NOT NULL,
      created_at timestamptz NOT NULL DEFAULT now()
    );

    CREATE TABLE memberships (
      id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
      tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
      user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
      role membership_role NOT NULL,
      created_at timestamptz NOT NULL DEFAULT now(),
      UNIQUE (user_id, tenant_id),
      -- Lets other tables use a composite foreign key (id, tenant_id), which proves
      -- a referenced row belongs to the SAME tenant.
      UNIQUE (id, tenant_id)
    );
    CREATE INDEX memberships_tenant_idx ON memberships (tenant_id);

    CREATE TABLE services (
      id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
      tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
      name text NOT NULL CHECK (length(name) BETWEEN 1 AND 120),
      duration_minutes integer NOT NULL CHECK (duration_minutes BETWEEN 5 AND 720),
      price_paise integer NOT NULL CHECK (price_paise >= 100),
      active boolean NOT NULL DEFAULT true,
      created_at timestamptz NOT NULL DEFAULT now(),
      UNIQUE (id, tenant_id)
    );
    CREATE INDEX services_tenant_idx ON services (tenant_id);

    CREATE TABLE staff_services (
      tenant_id uuid NOT NULL,
      staff_membership_id uuid NOT NULL,
      service_id uuid NOT NULL,
      PRIMARY KEY (staff_membership_id, service_id),
      FOREIGN KEY (staff_membership_id, tenant_id) REFERENCES memberships (id, tenant_id) ON DELETE CASCADE,
      FOREIGN KEY (service_id, tenant_id) REFERENCES services (id, tenant_id) ON DELETE CASCADE
    );
    CREATE INDEX staff_services_tenant_idx ON staff_services (tenant_id);

    -- Weekly working hours. weekday: 1 = Monday … 7 = Sunday (ISO).
    -- Times are minutes after local midnight in the tenant's timezone (540 = 09:00).
    CREATE TABLE availability_rules (
      id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
      tenant_id uuid NOT NULL,
      staff_membership_id uuid NOT NULL,
      weekday smallint NOT NULL CHECK (weekday BETWEEN 1 AND 7),
      start_minute integer NOT NULL CHECK (start_minute BETWEEN 0 AND 1439),
      end_minute integer NOT NULL CHECK (end_minute BETWEEN 1 AND 1440),
      CHECK (end_minute > start_minute),
      FOREIGN KEY (staff_membership_id, tenant_id) REFERENCES memberships (id, tenant_id) ON DELETE CASCADE
    );
    CREATE INDEX availability_rules_tenant_idx ON availability_rules (tenant_id);
    CREATE INDEX availability_rules_staff_idx ON availability_rules (staff_membership_id, weekday);

    CREATE TABLE time_off (
      id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
      tenant_id uuid NOT NULL,
      staff_membership_id uuid NOT NULL,
      start_at timestamptz NOT NULL,
      end_at timestamptz NOT NULL,
      reason text,
      CHECK (end_at > start_at),
      FOREIGN KEY (staff_membership_id, tenant_id) REFERENCES memberships (id, tenant_id) ON DELETE CASCADE
    );
    CREATE INDEX time_off_tenant_idx ON time_off (tenant_id);
    CREATE INDEX time_off_staff_idx ON time_off (staff_membership_id, start_at);

    CREATE TABLE bookings (
      id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
      tenant_id uuid NOT NULL,
      service_id uuid NOT NULL,
      staff_membership_id uuid NOT NULL,
      customer_membership_id uuid NOT NULL,
      start_at timestamptz NOT NULL,
      end_at timestamptz NOT NULL,
      status booking_status NOT NULL,
      -- Price is copied from the service when booking, so later price changes
      -- never change what an existing booking costs.
      price_paise integer NOT NULL CHECK (price_paise >= 0),
      hold_expires_at timestamptz,
      cancelled_at timestamptz,
      created_at timestamptz NOT NULL DEFAULT now(),
      updated_at timestamptz NOT NULL DEFAULT now(),
      CHECK (end_at > start_at),
      CHECK (status <> 'HELD' OR hold_expires_at IS NOT NULL),
      UNIQUE (id, tenant_id),
      FOREIGN KEY (service_id, tenant_id) REFERENCES services (id, tenant_id),
      FOREIGN KEY (staff_membership_id, tenant_id) REFERENCES memberships (id, tenant_id),
      FOREIGN KEY (customer_membership_id, tenant_id) REFERENCES memberships (id, tenant_id),

      -- THE double-booking guard. Two rows for the same staff member whose time
      -- ranges overlap (&&) cannot both be HELD/CONFIRMED. Postgres enforces this
      -- even when two requests arrive at the same instant.
      -- '[)' means start is included, end is excluded, so 10:00-10:30 and
      -- 10:30-11:00 do NOT overlap.
      CONSTRAINT no_overlapping_bookings EXCLUDE USING gist (
        staff_membership_id WITH =,
        tstzrange(start_at, end_at, '[)') WITH &&
      ) WHERE (status IN ('HELD', 'CONFIRMED'))
    );
    CREATE INDEX bookings_tenant_start_idx ON bookings (tenant_id, start_at);
    CREATE INDEX bookings_customer_idx ON bookings (customer_membership_id, start_at);
    CREATE INDEX bookings_held_expiry_idx ON bookings (hold_expires_at) WHERE status = 'HELD';

    CREATE TABLE payments (
      id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
      tenant_id uuid NOT NULL,
      booking_id uuid NOT NULL,
      provider text NOT NULL,
      provider_order_id text NOT NULL UNIQUE,
      provider_payment_id text,
      provider_refund_id text,
      amount_paise integer NOT NULL CHECK (amount_paise > 0),
      currency char(3) NOT NULL,
      status payment_status NOT NULL DEFAULT 'CREATED',
      refund_reason text,
      created_at timestamptz NOT NULL DEFAULT now(),
      updated_at timestamptz NOT NULL DEFAULT now(),
      FOREIGN KEY (booking_id, tenant_id) REFERENCES bookings (id, tenant_id)
    );
    CREATE INDEX payments_tenant_idx ON payments (tenant_id);
    CREATE INDEX payments_booking_idx ON payments (booking_id);

    -- Every webhook we accept is stored once. The UNIQUE event_id is what makes
    -- webhook handling idempotent.
    CREATE TABLE webhook_events (
      id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
      provider text NOT NULL,
      event_id text NOT NULL UNIQUE,
      type text NOT NULL,
      payload jsonb NOT NULL,
      received_at timestamptz NOT NULL DEFAULT now(),
      processed_at timestamptz
    );

    -- Emails we owe a customer. Rows are written in the SAME transaction as the
    -- booking change (an "outbox"), so an email can't be lost if the job queue is down.
    CREATE TABLE notifications (
      id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
      tenant_id uuid NOT NULL,
      booking_id uuid NOT NULL,
      type notification_type NOT NULL,
      status notification_status NOT NULL DEFAULT 'PENDING',
      scheduled_for timestamptz NOT NULL DEFAULT now(),
      attempts integer NOT NULL DEFAULT 0,
      last_error text,
      sent_at timestamptz,
      created_at timestamptz NOT NULL DEFAULT now(),
      FOREIGN KEY (booking_id, tenant_id) REFERENCES bookings (id, tenant_id) ON DELETE CASCADE
    );
    CREATE INDEX notifications_tenant_idx ON notifications (tenant_id, created_at DESC);
    CREATE INDEX notifications_due_idx ON notifications (scheduled_for) WHERE status = 'PENDING';

    CREATE TABLE audit_logs (
      id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
      tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
      actor_user_id uuid REFERENCES users(id) ON DELETE SET NULL,
      action text NOT NULL,
      entity text NOT NULL,
      entity_id uuid,
      before jsonb,
      after jsonb,
      created_at timestamptz NOT NULL DEFAULT now()
    );
    CREATE INDEX audit_logs_tenant_idx ON audit_logs (tenant_id, created_at DESC);
  `.execute(db);
}

export async function down(db: Kysely<unknown>): Promise<void> {
  await sql`
    DROP TABLE IF EXISTS audit_logs, notifications, webhook_events, payments, bookings,
      time_off, availability_rules, staff_services, services, memberships, users, tenants CASCADE;
    DROP TYPE IF EXISTS notification_status, notification_type, payment_status, booking_status, membership_role;
  `.execute(db);
}
